.target sm_89
.address_size 64
.visible .entry tanh_kernel(
    .param .u64 param_in,
    .param .u64 param_out,
    .param .u64 param_n
)
{
    .reg .pred %p1;
    .reg .pred %p2;
    .reg .b32 %r1;
    .reg .b32 %r2;
    .reg .b32 %r3;
    .reg .b64 %rd1;
    .reg .b64 %rd2;
    .reg .b64 %rd3;
    .reg .b64 %rd4;
    .reg .b64 %rd5;
    .reg .b64 %rd6;
    .reg .b64 %rd7;
    .reg .b64 %rd8;
    .reg .b64 %rd9;
    .reg .b64 %rd10;
    .reg .b64 %rd11;
    .reg .b64 %rd12;
    .reg .b64 %rd13;
    .reg .b64 %rd14;
    .reg .f32 %f1;
    .reg .f32 %f2;
    .reg .f32 %f3;
    .reg .f32 %f4;
    .reg .f32 %f5;
    .reg .f32 %f6;
    .reg .f32 %f7;
    .reg .f32 %f8;
    .reg .f32 %f9;
    .reg .f32 %f10;
    .reg .f32 %f11;
    .reg .f32 %f12;
    .reg .f32 %f13;
    .reg .f32 %f14;
    .reg .f32 %f15;
    .reg .f32 %f16;
    ld.param.u64 %rd1, [param_in];
    ld.param.u64 %rd2, [param_out];
    ld.param.u64 %rd3, [param_n];
    // rd4 = global thread id; rd5 = total threads; rd13 = 2 * total threads
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.u32 %r1, %r1, %r2, %r3;
    cvt.u64.u32 %rd4, %r1;
    mov.u32 %r2, %nctaid.x;
    mov.u32 %r3, %ntid.x;
    mul.lo.u32 %r2, %r2, %r3;
    cvt.u64.u32 %rd5, %r2;
    add.s64 %rd13, %rd5, %rd5;
    // rd8 = number of complete float4 vectors = n >> 2
    shr.u64 %rd8, %rd3, 2;
    mov.u64 %rd6, %rd4;
