    setp.ge.u64 %p1, %rd6, %rd8;
    @%p1 bra TAIL;
    add.s64 %rd11, %rd6, %rd5;
    setp.ge.u64 %p2, %rd11, %rd8;
    @%p2 bra SINGLE;
