    ld.global.nc.v4.f32 {%f9, %f10, %f11, %f12}, [%rd14];
    tanh.approx.f32 %f5, %f1;
    tanh.approx.f32 %f6, %f2;
    tanh.approx.f32 %f7, %f3;
    tanh.approx.f32 %f8, %f4;
    tanh.approx.f32 %f13, %f9;
    tanh.approx.f32 %f14, %f10;
    tanh.approx.f32 %f15, %f11;
    tanh.approx.f32 %f16, %f12;
    add.s64 %rd9, %rd2, %rd7;
    add.s64 %rd14, %rd2, %rd12;
    st.global.v4.f32 [%rd9], {%f5, %f6, %f7, %f8};
    st.global.v4.f32 [%rd14], {%f13, %f14, %f15, %f16};
    bra ADVANCE;
SINGLE:
    // Only the first float4 vector is in bounds
    shl.b64 %rd7, %rd6, 4;
    add.s64 %rd9, %rd1, %rd7;
    ld.global.nc.v4.f32 {%f1, %f2, %f3, %f4}, [%rd9];
    tanh.approx.f32 %f5, %f1;
    tanh.approx.f32 %f6, %f2;
    tanh.approx.f32 %f7, %f3;
    tanh.approx.f32 %f8, %f4;
    add.s64 %rd9, %rd2, %rd7;
    st.global.v4.f32 [%rd9], {%f5, %f6, %f7, %f8};
